2055	/**
2056	 * @brief 跟车：改中心经纬度。未越 overscan 只平移 canvas。
2057	 */
2058	void vmap_view_set_center(vmap_view_t * view, double lon, double lat)
2059	{
2060	    int now_x = 0;
2061	    int now_y = 0;
2062	    int base_x = 0;
2063	    int base_y = 0;
2064	    double dx;
2065	    double dy;
2066	    double limit;
2067	
2068	    if (!view) {
2069	        return;
2070	    }
2071	
2072	    vmap_latlong_to_pixel(lat, lon, view->zoom, &now_x, &now_y);
2073	    vmap_latlong_to_pixel(view->render_lat, view->render_lon, view->zoom, &base_x, &base_y);
2074	
2075	    dx = (now_x - base_x) * view->scale;
2076	    dy = (now_y - base_y) * view->scale;
2077	    view->lon = lon;
2078	    view->lat = lat;
2079	
2080	    /*
2081	     * Follow must not decode tiles. vmap_tile_cache_warm() is a blocking
2082	     * LFS parse (~150ms) on this thread; doing it every GNSS tick once pan
2083	     * crossed the old prefetch threshold pinned bicycle_ui at ~80% idle~10%.
2084	     * New tiles load in vmap_view_render_pump() when the canvas rebases.
2085	     */
2086	    limit = (double)view->margin - (double)VMAP_PAN_GUARD;
2087	
2088	    /*
2089	     * 航向朝上时，屏上看到的是**旋转后**的视口：它的四角离骑手是半对角线
2090	     * r = hypot(view_w/2, view_h/2)（240x216 → 161 px），画布必须盖住它，否则
2091	     * 45° 附近四角露底。骑手到画布边的余量 = margin + view_h/2 - |pan|，要求
2092	     * 不小于 r ⇒ pan <= margin - (r - view_h/2) - guard。取较紧的竖向。
2093	     */
2094	    if (view->heading_up) {
2095	        const double r = hypot((double)view->view_w / 2.0,
2096	            (double)view->view_h / 2.0);
2097	
2098	        limit -= r - (double)view->view_h / 2.0;
2099	        if (limit < 8.0) {
2100	            limit = 8.0;
2101	        }
2102	    }
2103	
2104	    if (dx >= -limit && dx <= limit && dy >= -limit && dy <= limit) {
2105	        bicycle_c_debug_map_soft_pan();
2106	        vmap_view_apply_canvas_pos(view, dx, dy);
2107	        vmap_follow_log(view, lon, lat);
2108	        return;
2109	    }
2110	
2111	    /* Soft-pan even when tiles cannot be reloaded (BLE LFS hold / in-flight pump). */
2112	    if (view->pump_phase != 0 || myvendor_mtp_lfs_quiesce()) {
2113	        bicycle_c_debug_map_soft_pan();
2114	        vmap_view_apply_canvas_pos(view,
2115	            vmap_clamp_d(dx, -limit, limit),
2116	            vmap_clamp_d(dy, -limit, limit));
2117	        vmap_follow_log(view, lon, lat);
2118	        return;
2119	    }
2120	
2121	    bicycle_c_debug_map_full_render();
2122	    vmap_view_render(view);
2123	}
