131	static void vmap_fps_probe_cb(lv_event_t * e)
132	{
133	    const lv_event_code_t code = lv_event_get_code(e);
134	    uint32_t now = lv_tick_get();
135	    uint32_t dt;
136	    uint32_t win;
137	
138	    if (code == LV_EVENT_REFR_START) {
139	        s_fps.refr_t0 = now;
140	        return;
141	    }
142	    if (code == LV_EVENT_REFR_READY) {
143	        /* 只统计真的画了的刷新（rendered 由 RENDER_START 置位）。 */
144	        if (s_fps.rendered) {
145	            s_fps.refr_sum += lv_tick_elaps(s_fps.refr_t0);
146	            s_fps.refr_n++;
147	            s_fps.rendered = false;
148	        }
149	        return;
150	    }
151	    if (code == LV_EVENT_RENDER_START) {
152	        s_fps.rendered = true;
153	        s_fps.t0 = now;
154	        return;
155	    }
156	    if (code != LV_EVENT_RENDER_READY) {
157	        return;
158	    }
159	
160	    dt = lv_tick_elaps(s_fps.t0);
161	    if (s_fps.win == 0u) {
162	        s_fps.win = now;
163	    }
164	    s_fps.n++;
165	    s_fps.sum += dt;
166	    if (dt > s_fps.max) {
167	        s_fps.max = dt;
168	    }
169	
170	    win = lv_tick_elaps(s_fps.win);
171	    if (win < 2000u) {
172	        return;
173	    }
174	    if (s_fps.n > 0u) {
175	        /* fps 用 x10 定点：n * 10000 / win。refr=整次刷新，ovh=刷新管线开销。 */
176	        const uint32_t refr = (s_fps.refr_n > 0u) ? (s_fps.refr_sum / s_fps.refr_n) : 0u;
177	        const uint32_t draw = s_fps.sum / s_fps.n;
178	
179	        syslog(LOG_DEBUG,
180	            "[mapfps] n=%u fps=%u.%u avg=%ums max=%ums refr=%ums ovh=%ums win=%ums",
181	            (unsigned)s_fps.n,
182	            (unsigned)(s_fps.n * 10000u / win / 10u),
183	            (unsigned)(s_fps.n * 10000u / win % 10u),
184	            (unsigned)draw,
185	            (unsigned)s_fps.max,
186	            (unsigned)refr,
187	            (unsigned)((refr > draw) ? (refr - draw) : 0u),
188	            (unsigned)win);
189	    }
190	    s_fps.n = 0u;
191	    s_fps.sum = 0u;
192	    s_fps.max = 0u;
193	    s_fps.refr_sum = 0u;
194	    s_fps.refr_n = 0u;
195	    /* 不清 `rendered`：本次刷新的 REFR_READY 就在本回调返回之后才到，
196	     * 提前清掉会把每个窗口的最后一个样本丢掉（样本数与 draw 对不上）。 */
197	    s_fps.win = now;
198	}
