2728	        VMAP_PERF_T1P(VMAP_PERF_NAV_SLOT());
2729	    }
2730	#endif
2731	
2732	    /* 航向朝上时路名会随画布转成斜字：该模式不烘焙标签（第一版取舍，见
2733	     * vmap_config.h 的说明）。 */
2734	    if (labels && view->font && !view->heading_up
2735	        && view->label_col.count > 0) {
2736	        VMAP_PERF_T0();
2737	        labels_drawn = vmap_label_paint_to_canvas(
2738	            view->canvas, &view->label_col, view->font,
2739	            view->scale, view->pump_dirty_n,
2740	            view->pump_dirty_x1, view->pump_dirty_y1,
2741	            view->pump_dirty_x2, view->pump_dirty_y2, &label_drawn);
