void vmap_render_clip_reset(vmap_canvas_t * c)
{
    if (c) {
        c->clip_n = 0;
    }
}

void vmap_render_clip_add(vmap_canvas_t * c, int32_t x1, int32_t y1,
    int32_t x2, int32_t y2)
{
    uint8_t i;

    if (!c || c->clip_n >= VMAP_RENDER_DIRTY_MAX || x1 >= x2 || y1 >= y2) {
        return;
    }
    if (x1 < 0) {
        x1 = 0;
    }
    if (y1 < 0) {
        y1 = 0;
    }
    if (x2 > c->w) {
        x2 = c->w;
    }
    if (y2 > c->h) {
        y2 = c->h;
    }
    if (x1 >= x2 || y1 >= y2) {
        return;
    }

    i = c->clip_n;
    c->clip_x1[i] = x1;
    c->clip_y1[i] = y1;
    c->clip_x2[i] = x2;
    c->clip_y2[i] = y2;
    c->clip_n++;
}

